{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The closest structural analogue Rg1 (Morgan similarity 0.8765) showed poor brain distribution (14.59 ng/mL) in rats, directly indicating that this highly glycosylated protopanaxatriol scaffold has limited CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Re itself was detected in brain after oral administration, but brain concentrations were 8–15 times lower than plasma, demonstrating only low-level BBB crossing rather than meaningful exposure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ginsenoside Rh3, a less glycosylated analogue, reached 520 ng/g in hippocampus, showing that deglycosylated ginsenosides can achieve higher brain levels, but this transfers weakly to the tri-saccharide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable quantitative evidence (Rg1) shows poor brain penetration, and direct Re evidence indicates only low brain exposure relative to plasma. The large polar tri-saccharide structure and high efflux liability further support inadequate meaningful CNS access.",
  "evidence_gaps": [
    "No quantitative unbound brain concentration or functional CNS target engagement for Re.",
    "No dedicated brain/plasma Kp value for Re itself.",
    "Efflux transporter contribution to Re brain exposure is not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

